# The Atlas of Imagination — Exp 01 · Imagination Score as a point cloud (TouchDesigner, B/W)
#
# Run inside TouchDesigner (Textport: Alt+T), one line:
#   exec(open(r'D:\columbia\atlas_sample\td\atlas_td_build.py', encoding='utf-8').read())
#
# Builds /project1/atlas_points:
#   points  (Table DAT)   ← td/points/score_<n>_<id>.csv  (generated by td/build_points.py, same layout rules as Processing)
#   ctrl    (Constant CHOP) disperse 0–1 · auto 0/1 · speed
#   cloud   (Script CHOP)   base positions + dispersion  → instancing channels
#   geo     (Geometry COMP) instanced tiny spheres, constant white material
#   cam / render / OUT      black background, white points
import os, csv

WORK = 1                                    # which artwork to load (1 = The Dream of Paris)
ROOT = r'D:\columbia\atlas_sample\td'
POINTS_DIR = os.path.join(ROOT, 'points')

warnings = []
def setp(o, names, value):
    """Set the first parameter name that exists; record a warning if none does."""
    for n in ([names] if isinstance(names, str) else names):
        p = getattr(o.par, n, None)
        if p is not None:
            try:
                p.val = value
                return True
            except Exception as e:
                warnings.append(f'{o.name}.{n}: {e}')
                return False
    warnings.append(f'{o.name}: no parameter among {names}')
    return False

def setexpr(o, name, expr):
    p = getattr(o.par, name, None)
    if p is None:
        warnings.append(f'{o.name}: no parameter {name}'); return
    p.expr = expr

# ───────── find the point file ─────────
fname = [f for f in os.listdir(POINTS_DIR) if f.startswith(f'score_{WORK}_') and f.endswith('.csv')][0]
with open(os.path.join(POINTS_DIR, fname), encoding='utf-8') as f:
    rows = list(csv.reader(f, delimiter='\t'))

# ───────── container ─────────
parent_ = op('/project1')
old = parent_.op('atlas_points')
if old: old.destroy()
base = parent_.create(baseCOMP, 'atlas_points')
base.nodeX, base.nodeY = 0, -400

# points table (header renamed to plain names for instancing)
tbl = base.create(tableDAT, 'points')
tbl.clear()
tbl.appendRow(['tx', 'ty', 'tz', 'cr', 'cg', 'cb', 'ca', 's', 'group'])
for r in rows[1:]:
    tbl.appendRow(r)
tbl.nodeX, tbl.nodeY = -600, 200

# controls
ctrl = base.create(constantCHOP, 'ctrl')
for i, (n, v) in enumerate([('disperse', 0.0), ('auto', 1.0), ('speed', 0.6)]):
    setp(ctrl, f'name{i}', n); setp(ctrl, f'value{i}', v)
ctrl.nodeX, ctrl.nodeY = -600, 0

# Script CHOP callbacks
cb = base.create(textDAT, 'cloud_callbacks')
cb.text = r'''
import numpy as np
_cache = {}

def onSetupParameters(scriptOp):
    return

def onPulse(par):
    return

def onCook(scriptOp):
    t = op('points')
    key = (t.numRows, t[1, 0].val if t.numRows > 1 else '')
    if _cache.get('key') != key:
        data = np.array([[float(c.val) for c in r[:8]] for r in t.rows()[1:]], dtype=np.float32)
        rng = np.random.default_rng(3)
        _cache.update(key=key, base=data,
                      phase=rng.uniform(0, 6.283, (len(data), 3)).astype(np.float32),
                      dirn=rng.normal(0, 1, (len(data), 3)).astype(np.float32))
    data, ph, dirn = _cache['base'], _cache['phase'], _cache['dirn']
    ctrl = op('ctrl')
    speed = float(ctrl['speed'])
    tm = absTime.seconds * speed
    if float(ctrl['auto']) > 0.5:
        k = float((0.5 + 0.5 * np.sin(tm * 0.35)) ** 4)        # mostly legible, periodically dissolving
    else:
        k = float(ctrl['disperse'])
    pos = data[:, 0:3] + dirn * (k * 2.2) + np.sin(tm + ph) * (0.03 + 0.25 * k)
    scriptOp.clear()
    scriptOp.numSamples = len(data)
    for i, n in enumerate(('tx', 'ty', 'tz')):
        scriptOp.appendChan(n).vals = pos[:, i].tolist()
    bright = data[:, 3] * (1.0 - 0.35 * k)
    for n in ('cr', 'cg', 'cb'):
        scriptOp.appendChan(n).vals = bright.tolist()
    scriptOp.appendChan('s').vals = (data[:, 7] * 1.2).tolist()
    return
'''
cb.nodeX, cb.nodeY = -400, 200

cloud = base.create(scriptCHOP, 'cloud')
setp(cloud, 'callbacks', cb.path)
cloud.nodeX, cloud.nodeY = -400, 0

# cook every frame
ex = base.create(executeDAT, 'tick')
ex.text = "def onFrameStart(frame):\n    op('cloud').cook(force=True)\n    return\n"
setp(ex, 'framestart', True)
setp(ex, 'active', True)
ex.nodeX, ex.nodeY = -400, -200

# material
mat = base.create(constantMAT, 'mat_white')
mat.nodeX, mat.nodeY = -200, -200

# geometry with instancing
geo = base.create(geometryCOMP, 'geo')
for c in list(geo.children):
    c.destroy()
sph = geo.create(sphereSOP, 'dot')
setp(sph, 'rows', 5); setp(sph, 'cols', 6)
setp(sph, ['rad', 'radx'], 1.0)
sph.render = True; sph.display = True
setp(geo, 'material', mat.path)
setp(geo, 'instancing', True)
setp(geo, 'instanceop', cloud.path)
setp(geo, 'instancetx', 'tx'); setp(geo, 'instancety', 'ty'); setp(geo, 'instancetz', 'tz')
for ax in ('sx', 'sy', 'sz'):
    setp(geo, 'instance' + ax, 's')
setp(geo, ['instancer', 'instancecolorr'], 'cr')
setp(geo, ['instanceg', 'instancecolorg'], 'cg')
setp(geo, ['instanceb', 'instancecolorb'], 'cb')
setexpr(geo, 'ry', 'absTime.seconds * 5')            # slow turntable
geo.nodeX, geo.nodeY = -200, 0

# camera
tgt = base.create(nullCOMP, 'cam_target')
setp(tgt, 'tx', 0.0); setp(tgt, 'ty', 2.0); setp(tgt, 'tz', 0.0)
cam = base.create(cameraCOMP, 'cam')
setp(cam, 'tx', 8.5); setp(cam, 'ty', 6.5); setp(cam, 'tz', 11.0)
setp(cam, 'lookat', tgt.path)
cam.nodeX, cam.nodeY = 0, 200
tgt.nodeX, tgt.nodeY = 0, 350

# render
ren = base.create(renderTOP, 'render')
setp(ren, 'outputresolution', 'custom')
setp(ren, 'resolutionw', 1920); setp(ren, 'resolutionh', 1080)
setp(ren, 'camera', cam.path)
setp(ren, 'geometry', geo.path)
setp(ren, 'bgcolora', 1.0)
setp(ren, 'antialias', 'aa8x')
ren.nodeX, ren.nodeY = 200, 0

out = base.create(nullTOP, 'OUT')
out.inputConnectors[0].connect(ren)
out.nodeX, out.nodeY = 400, 0
out.viewer = True

note = base.create(textDAT, 'README')
note.text = (f'Imagination Score point cloud · {fname}\n'
             'ctrl: auto=1 breathes between legible and dissolved; set auto=0 and drag disperse 0–1 by hand.\n'
             'Brightness = evidence: white = text evidence, dim = image only, very dim = inference.\n'
             'Change WORK at the top of atlas_td_build.py and re-run to load another artwork.')
note.nodeX, note.nodeY = 400, 200

try:
    out.openViewer()
except Exception as e:
    warnings.append(f'openViewer: {e}')

print('Atlas point cloud built:', base.path, '·', fname, '·', tbl.numRows - 1, 'points')
if warnings:
    print('WARNINGS (paste these to Claude if it looks wrong):')
    for w in warnings:
        print('  -', w)
else:
    print('No warnings.')
